package io.github.turbopro.ism.operation.task;
import io.github.turbopro.ism.common.api.error.*;import io.github.turbopro.ism.common.infrastructure.tenant.TenantContext;import io.github.turbopro.ism.operation.OperationModels;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class TaskCenterService{private final TaskCenterMapper mapper;public TaskCenterService(TaskCenterMapper mapper){this.mapper=mapper;}public List<TaskCenterModels.TaskView>tasks(){var i=TenantContext.require();return mapper.tasks(i.tenantId(),i.actorId()).stream().map(this::view).toList();}public TaskCenterModels.TaskView task(long id){var i=TenantContext.require();var t=mapper.task(i.tenantId(),i.actorId(),id);if(t==null)throw new ApiException(CommonErrorCode.NOT_FOUND);return view(t);}@Transactional public TaskCenterModels.TaskView cancel(long id,int version){var i=TenantContext.require();if(mapper.cancel(i.tenantId(),i.actorId(),id,version)!=1)throw new ApiException(CommonErrorCode.CONFLICT);return task(id);}@Transactional public TaskCenterModels.TaskView retry(long id,int version){var i=TenantContext.require();if(mapper.retry(i.tenantId(),i.actorId(),id,version)!=1)throw new ApiException(CommonErrorCode.CONFLICT);return task(id);}private TaskCenterModels.TaskView view(OperationModels.AsyncTask t){return new TaskCenterModels.TaskView(Long.toString(t.id()),t.taskNo(),t.taskType(),t.status(),t.progress(),t.currentStage(),t.cancelRequested(),t.retryCount(),t.resultFileId()==null?null:Long.toString(t.resultFileId()),t.errorCode(),t.errorMessage(),t.version(),t.createdAt(),t.startedAt(),t.finishedAt());}}
